INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-13-z3-q83','nism-13-z3','A trader buys 1 lot (100) of stock futures at ₹3960 and squares off at ₹3890. The profit/(loss), ignoring costs, is:','["-₹7,000","₹7,000","-₹14,000","-₹70"]',0,'(3890 − 3960) × 100.',83) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort WHERE questions.quiz_id IS NOT excluded.quiz_id OR questions.question IS NOT excluded.question OR questions.options IS NOT excluded.options OR questions.answer IS NOT excluded.answer OR questions.explanation IS NOT excluded.explanation OR questions.sort IS NOT excluded.sort;
